/**
 * readApiResponse 사용 예시. 실제 네트워크 요청 없이 new Response와 Promise.reject로만 입력을 만든다.
 * 실행 부수효과가 없도록 runExamples()를 호출하는 쪽에서 결과를 출력한다.
 */
import { readApiResponse, type ApiResult } from "../web/src/lib/api-response";

const json = (body: unknown, status: number) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });

/** 성공 200: 본문을 그대로 data로 받는다. */
const listSuccess = () => json({ items: [], page: { nextCursor: null } }, 200);

/** 성공 204: 본문을 읽지 않고 data는 null이 된다. */
const updateNoContent = () => new Response(null, { status: 204 });

/** API 오류 400: 명세 v1 오류 본문이라 code·message·details가 그대로 살아남는다. */
const validationFailed = () =>
  json(
    {
      code: "VALIDATION_FAILED",
      message: "입력값을 확인해 주세요.",
      details: { violations: [{ field: "title", reason: "필수 항목입니다." }] },
    },
    400,
  );

/** API 오류 409: details.existingRequestId만 있는 형태. */
const alreadyRequested = () =>
  json(
    { code: "REQUEST_ALREADY_EXISTS", message: "이미 진행 중인 요청이 있습니다.", details: { existingRequestId: "req-1" } },
    409,
  );

/** 조회 실패: fetch 자체가 실패한 상황을 Promise.reject로 대신한다. */
const transportRejected = (): Promise<Response> => Promise.reject(new Error("network unreachable"));

/** 조회 실패: 오류 상태인데 본문이 명세와 다르면 api-error가 아니라 lookup-failed가 된다. */
const brokenErrorBody = () => json({ error: "bad request" }, 400);

/** kind로 갈라서 호출 화면이 할 일을 정한다. 상태별 화면 이동은 여기서 정하지 않는다. */
export type Handled =
  | { action: "use-data"; status: number; data: unknown }
  | { action: "show-api-error"; status: number; code: string; message: string; fields: string[]; existingRequestId: string | null }
  | { action: "retry-lookup"; status: number | null; message: string };

export function handle(result: ApiResult): Handled {
  switch (result.kind) {
    case "success":
      return { action: "use-data", status: result.status, data: result.data };
    case "api-error":
      return {
        action: "show-api-error",
        status: result.status,
        code: result.code,
        message: result.message,
        fields: result.details?.violations?.map((violation) => violation.field) ?? [],
        existingRequestId: result.details?.existingRequestId ?? null,
      };
    case "lookup-failed":
      return {
        action: "retry-lookup",
        status: result.status,
        message: "요청 결과를 확인하지 못했습니다. 다시 불러와 현재 상태를 확인해 주세요.",
      };
  }
}

function describe(handled: Handled): string {
  switch (handled.action) {
    case "use-data":
      return `성공 ${handled.status}: ${handled.data === null ? "본문 없음" : JSON.stringify(handled.data)}`;
    case "show-api-error": {
      const fields = handled.fields.length > 0 ? ` 항목=${handled.fields.join(",")}` : "";
      const existing = handled.existingRequestId !== null ? ` 기존요청=${handled.existingRequestId}` : "";
      return `API 오류 ${handled.status} ${handled.code}: ${handled.message}${fields}${existing}`;
    }
    case "retry-lookup":
      return `조회 실패 ${handled.status ?? "상태 없음"}: ${handled.message}`;
  }
}

const cases: { name: string; input: () => Response | Promise<Response> }[] = [
  { name: "성공 200", input: listSuccess },
  { name: "성공 204", input: updateNoContent },
  { name: "API 오류 400", input: validationFailed },
  { name: "API 오류 409", input: alreadyRequested },
  { name: "조회 실패(Promise.reject)", input: transportRejected },
  { name: "조회 실패(오류 본문 손상)", input: brokenErrorBody },
];

export async function runExamples(): Promise<string[]> {
  const lines: string[] = [];
  for (const { name, input } of cases) {
    // fetch의 Promise를 그대로 넘기는 호출 모양을 유지한다.
    const handled = handle(await readApiResponse(input()));
    lines.push(`${name} -> ${handled.action} / ${describe(handled)}`);
  }
  return lines;
}

/**
 * web/src/lib/api-response.ts의 readApiResponse 사용 예시.
 *
 * 실제 네트워크 요청 없이 new Response(성공·API 오류)와 Promise.reject(조회 실패)로
 * 세 가지 결과를 만들고, 반환된 ApiResult를 kind로 나눠 다룬다.
 *
 * 실행: web/README.md의 테스트와 같은 방식으로 Node.js 24의 타입 제거를 쓴다.
 *   node .eval-output/api-response-example.ts
 * 이 파일은 web/ 밖의 예시이므로 web의 tsconfig include·`@/` 별칭 대상이 아니다.
 * import에 `.ts`를 붙인 것은 Node 실행을 위한 것이며, tsc로 직접 검사하려면
 * allowImportingTsExtensions가 필요하다.
 */
import { readApiResponse, type ApiResult } from "../web/src/lib/api-response.ts";

const JSON_HEADERS = { "content-type": "application/json" };

/** 성공 200. 분석 상태 EMPTY·PARTIAL_FAILED는 HTTP 오류로 바뀌지 않고 data에 그대로 담긴다. */
function successResponse(): Response {
  const body = { processing: "PARTIAL_FAILED", items: [{ catchId: "catch-1" }] };
  return new Response(JSON.stringify(body), { status: 200, headers: JSON_HEADERS });
}

/** API 오류 400. 공통 Error 스키마의 code·message는 보존되고 알려진 details만 전달된다. */
function apiErrorResponse(): Response {
  const body = {
    code: "VALIDATION_FAILED",
    message: "제목을 입력해 주세요.",
    details: { violations: [{ field: "title", reason: "required" }] },
  };
  return new Response(JSON.stringify(body), { status: 400, headers: JSON_HEADERS });
}

/** 네트워크 실패. fetch의 Promise를 await하지 않고 그대로 넘겨야 조회 실패로 해석된다. */
function networkFailure(): Promise<Response> {
  return Promise.reject(new TypeError("fetch failed"));
}

/**
 * kind별로 화면이 할 일을 나눈다. 성공의 data는 unknown이므로 기능별 스키마를 확인한 뒤 쓰고,
 * 조회 실패는 빈 결과나 0건으로 바꾸지 않는다. 모르는 code는 일반 오류 안내로 처리한다.
 */
function describeResult(result: ApiResult): string {
  switch (result.kind) {
    case "success":
      return result.data === null
        ? `성공 ${result.status}: 본문 없음(204). 현재 상태를 다시 조회해 표시한다`
        : `성공 ${result.status}: data는 unknown이므로 기능별 스키마 확인 후 사용한다`;
    case "api-error": {
      const violations = result.details?.violations
        ?.map(({ field, reason }) => `${field}=${reason}`)
        .join(", ");
      const guide = result.status === 401
        ? "다시 로그인한 뒤 확인하도록 안내한다(자동 이동은 하지 않는다)"
        : result.message;
      return `API 오류 ${result.status} ${result.code}: ${guide}`
        + (violations ? ` / 입력 확인: ${violations}` : "");
    }
    case "lookup-failed":
      return `조회 실패 ${result.status ?? "HTTP 응답 없음"}: ${result.code}.`
        + " 결과를 확인하지 못했음을 알리고 다시 불러오기를 안내한다";
  }
}

/** 요청은 await 직전에 만든다. 미리 만든 reject Promise는 처리되지 않은 거부로 보고될 수 있다. */
const cases: { label: string; send: () => Response | Promise<Response> }[] = [
  { label: "성공 응답", send: successResponse },
  { label: "API 오류 응답", send: apiErrorResponse },
  { label: "조회 실패(네트워크)", send: networkFailure },
];

for (const { label, send } of cases) {
  const result = await readApiResponse(send());
  console.log(`${label} -> ${describeResult(result)}`);
}
